def find(items, target):
    lo, hi = 0, len(items)
    while lo < hi:
        mid = (lo + hi) // 2
        if items[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo
# [1,3,5,7], target=5
# [lo,hi): [0,4) -> mid2 -> [0,2)
