import json
def parse_note(raw):
    if len(raw.encode("utf-8")) > 200: raise ValueError("too large")
    data=json.loads(raw)
    if not isinstance(data,dict) or set(data)!={"body"}: raise ValueError("shape")
    if not isinstance(data["body"],str): raise ValueError("type")
    return data["body"]
print(parse_note('{"body":"demo"}'))
# expected: demo; no network or file reference is interpreted.

def parse_count(text):
    # Intended grammar: one digit, colon, exactly that many letters
    n = int(text[0])       # empty input unexpectedly raises IndexError
    if text[1] != ":": raise ValueError("separator")
    body=text[2:]
    if len(body)!=n or not body.isalpha(): raise ValueError("body")
    return body

